For the PackBits encoder and decoder, the key is to correctly parse and generate packets according to the format specifications. The decoder processes header bytes to determine literal or repeat sequences, validating data integrity. The encoder greedily identifies runs and applies the encoding rules for literals and repeats, splitting long runs into multiple packets.

```python
def packbits_decode(data):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError
    result = bytearray()
    i = 0
    while i < len(data):
        if i >= len(data):
            break
        h = data[i]
        i += 1
        if h == -128:
            continue
        elif h >= 0:
            count = h + 1
            if i + count > len(data):
                raise ValueError
            result.extend(data[i:i+count])
            i += count
        else:
            if i >= len(data):
                raise ValueError
            b = data[i]
            i += 1
            count = 1 - h
            for _ in range(count):
                result.append(b)
    return bytes(result)

def packbits_encode(data):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError
    if not data:
        return b''
    result = bytearray()
    i = 0
    while i < len(data):
        # Find run length
        j = i
        while j < len(data) and data[j] == data[i] and j - i < 128:
            j += 1
        run_len = j - i
        if run_len >= 3:
            # Output repeat packet
            count = run_len
            while count > 128:
                result.append(0x81)  # -127
                result.append(data[i])
                count -= 128
            result.append(1 - count)
            result.append(data[i])
            i += run_len
        else:
            # Output literal packet
            max_len = 128
            j = i
            while j < min(i + 128, len(data)):
                # Check if next bytes form a run of 3
                run_start = j
                run_val = data[run_start]
                run_count = 1
                while run_start + run_count < len(data) and data[run_start + run_count] == run_val and run_count < 128:
                    run_count += 1
                if run_count >= 3 and j + 1 == run_start:
                    break
                j += 1
            literal_len = j - i
            result.append(literal_len - 1)
            result.extend(data[i:j])
            i = j
    return bytes(result)
