import re
from itertools import zip_longest

def semver_sort(versions):
    if not isinstance(versions, (list, tuple)):
        raise ValueError
    for v in versions:
        if not isinstance(v, str):
            raise ValueError
    # Parse and validate each version
    parsed = []
    for version in versions:
        # Validate and parse the version string
        if not version:
            raise ValueError
        # Split core, prerelease, build
        core = ''
        prerelease = ''
        build = ''
        hyphen_idx = version.find('-')
        plus_idx = version.find('+')
        split_idx = -1
        split_char = ''
        if hyphen_idx != -1:
            split_idx = hyphen_idx
            split_char = '-'
        if plus_idx != -1:
            if split_idx == -1 or plus_idx < split_idx:
                split_idx = plus_idx
                split_char = '+'
        if split_idx != -1:
            core = version[:split_idx]
            rest = version[split_idx+1:]
            if split_char == '-':
                # Now check for '+' in rest
                plus_in_rest = rest.find('+')
                if plus_in_rest != -1:
                    prerelease = rest[:plus_in_rest]
                    build = rest[plus_in_rest+1:]
                else:
                    prerelease = rest
            else:  # split_char == '+'
                # No hyphen after core, so no prerelease
                build = rest
        else:
            core = version
        # Validate core
        core_parts = core.split('.')
        if len(core_parts) != 3:
            raise ValueError
        for part in core_parts:
            if not part.isdigit():
                raise ValueError
            if len(part) > 1 and part.startswith('0'):
                raise ValueError
        major = int(core_parts[0])
        minor = int(core_parts[1])
        patch = int(core_parts[2])
        # Validate prerelease
        if split_char == '-':
            if not rest:
                raise ValueError
            prerelease = rest
            prerelease_ids = prerelease.split('.')
            if not prerelease_ids or '' in prerelease_ids:
                raise ValueError
            for pid in prerelease_ids:
                if not re.fullmatch(r'([0-9]+|([a-zA-Z0-9\-]+))', pid):
                    raise ValueError
                if pid.isdigit():
                    if len(pid) > 1 and pid[0] == '0':
                        raise ValueError
        else:
            prerelease = ''
        # Validate build
        if '+' in version:
            if split_char == '+':
                build = rest
            else:
                build = rest.split('+', 1)[1] if '+' in rest else ''
            build_ids = build.split('.')
            if '' in build_ids:
                raise ValueError
            for bid in build_ids:
                if not re.fullmatch(r'([a-zA-Z0-9\-]+)', bid):
                    raise ValueError
        # Create sort key
        def prerelease_key(ids):
            result = []
            for id in ids:
                if id.isdigit():
                    result.append((0, int(id)))
                else:
                    result.append((1, id))
            return result
        key = (major, minor, patch, 
               (prerelease if prerelease else None, prerelease_key(prerelease.split('.'))) if prerelease else (None, None))
        parsed.append((version, key))
    # Sort by key
    def sort_key(item):
        (major, minor, patch), (prerelease_info, prerelease_ids) = item[1][0], item[1][1]
        # For versions with prerelease, they come after those without
        return (major, minor, patch, 0 if prerelease_info is None else 1, 
                (prerelease_ids if prerelease_info is not None else []))
    sorted_versions = sorted(parsed, key=sort_key)
    return [v[0] for v in sorted_versions]
