def justify_lines(text, width):
    if not isinstance(text, str):
        raise ValueError
    if not isinstance(width, int) or isinstance(width, bool):
        raise ValueError
    if width < 1:
        raise ValueError
    # Split text into tokens
    words = text.split()
    tokens = []
    for word in words:
        length = len(word)
        if length > width:
            # Split word into chunks of 'width' size
            for i in range(0, length, width):
                tokens.append(word[i:i+width])
        else:
            tokens.append(word)
    # Build lines greedily
    lines = []
    current_line = []
    current_length = 0
    for token in tokens:
        token_len = len(token)
        if not current_line:
            new_length = token_len
        else:
            new_length = current_length + 1 + token_len
        if new_length <= width:
            current_line.append(token)
            current_length = new_length
        else:
            lines.append(current_line)
            current_line = [token]
            current_length = token_len
    if current_line:
        lines.append(current_line)
    # Justify lines
    result = []
    for i, line in enumerate(lines):
        if len(line) == 0:
            continue
        if i == len(lines) - 1 or len(line) == 1:
            # Left-aligned
            line_str = ' '.join(line)
            line_str += ' ' * (width - len(line_str))
            result.append(line_str)
        else:
            # Fully justified
            total_spaces = width - sum(len(t) for t in line)
            gaps = len(line) - 1
            if gaps == 0:
                # Shouldn't happen since len(line) > 1
                result.append(line[0] + ' ' * (width - len(line[0])))
            else:
                base, extra = divmod(total_spaces, gaps)
                spaces = [base + 1 if j < extra else base for j in range(gaps)]
                line_str = line[0]
                for j in range(gaps):
                    line_str += ' ' * spaces[j] + line[j + 1]
                result.append(line_str)
    return result
