        hyphen_idx = version.find('-')
        plus_idx = version.find('+')
        split_idx = -1
        split_char = ''
        if hyphen_idx != -1 and plus_idx != -1:
            if hyphen_idx < plus_idx:
                split_idx = hyphen_idx
                split_char = '-'
            else:
                split_idx = plus_idx
                split_char = '+'
        elif hyphen_idx != -1:
            split_idx = hyphen_idx
            split_char = '-'
        elif plus_idx != -1:
            split_idx = plus_idx
            split_char = '+'
        core = version[:split_idx] if split_idx != -1 else version
        # Validate core
        core_match = core_pattern.match(core)
        if not core_match:
            raise ValueError
        major, minor, patch = map(int, core_match.groups())
        # Extract prerelease and build
        if split_char == '-':
            rest = version[split_idx+1:]
            plus_in_rest = rest.find('+')
            if plus_in_rest != -1:
                prerelease = rest[:plus_in_rest]
                build = rest[plus_in_rest+1:]
            else:
