To solve this problem, we need to write two functions about integer partitions: `count_partitions` and `kth_partition`. These functions should handle various constraints such as maximum part size and whether parts must be distinct. The functions must be efficient, especially since the maximum value of `n` can be 300, leading to very large counts.

### Approach

1. **count_partitions Function**:
   - This function counts the number of integer partitions of `n` with optional constraints on maximum part size and whether parts must be distinct.
   - We use a recursive helper function with memoization to efficiently compute the count. The helper function considers each possible part size, starting from the maximum allowed, and recursively computes the partitions for the remaining value.
   - The helper function handles both distinct and non-distinct partitions, adjusting the maximum part size for subsequent parts accordingly.

2. **kth_partition Function**:
   - This function returns the k-th partition in lexicographic order. The partitions are generated in non-increasing order (strictly decreasing for distinct partitions).
   - The function builds the partition step by step, choosing each part such that the resulting partition is the k-th in order. For each possible part, it calculates how many partitions can be formed with that part and uses this to determine the correct part at each step.

### Solution Code

```python
import sys
from functools import lru_cache

def count_partitions(n, max_part=None, distinct=False):
    if not isinstance(n, int) or not isinstance(distinct, bool) or (max_part is not None and not isinstance(max_part, int)):
        raise ValueError
    if n < 0 or (max_part is not None and max_part < 0):
        raise ValueError
    if n == 0:
        return 1
    max_part = n if max_part is None else max_part
    if max_part < 1:
        return 0 if n != 0 else 1

    @lru_cache(maxsize=None)
    def helper(remaining, max_p, is_distinct):
        if remaining == 0:
            return 1
        if remaining < 0:
            return 0
        if max_p == 0:
            return 0
        total = 0
        start = min(max_p, remaining)
        for part in range(start, 0, -1):
            next_max = part - 1 if is_distinct else part
            total += helper(remaining - part, next_max, is_distinct)
        return total

    return helper(n, max_part, distinct)

def kth_partition(n, k, max_part=None, distinct=False):
    if not isinstance(n, int) or not isinstance(k, int) or not isinstance(distinct, bool) or (max_part is not None and not isinstance(max_part, int)):
        raise ValueError
    if n < 0 or k < 0 or (max_part is not None and max_part < 0):
        raise ValueError
    total = count_partitions(n, max_part, distinct)
    if k >= total or k < 0:
        raise ValueError
    if n == 0:
        return ()
    max_part = n if max_part is None else max_part

    def helper_kth(remaining, max_p, is_distinct, k_val):
        if remaining == 0:
            return []
        if remaining < 0:
            return None
        if max_p == 0:
            return None
        parts = []
        start = min(max_p, remaining)
        for part in range(1, start + 1):
            if is_distinct and len(parts) > 0 and part >= parts[-1]:
                continue
            next_max = part - 1 if is_distinct else part
            cnt = count_partitions(remaining - part, next_max, is_distinct)
            if cnt > k_val:
                next_part = part
                if is_distinct:
                    new_max = next_part - 1
                else:
                    new_max = next_part
                res = helper_kth(remaining - part, new_max, is_distinct, k_val)
                if res is not None:
                    return [next_part] + res
            else:
                k_val -= cnt
        return None

    if distinct:
        current_max = max_part
        current_remaining = n
        partition = []
        while current_remaining > 0:
            found = False
            for part in range(1, current_max + 1):
                if len(partition) > 0 and part >= partition[-1]:
                    continue
                next_max = part - 1
                cnt = count_partitions(current_remaining - part, next_max, distinct)
                if cnt > k:
                    partition.append(part)
                    current_remaining -= part
                    current_max = part - 1
                    found = True
                    break
                else:
                    k -= cnt
            if not found:
                return None
        return tuple(partition)
    else:
        current_max = max_part
        current_remaining = n
        partition = []
        while current_remaining > 0:
            found = False
            for part in range(1, current_max + 1):
                cnt = count_partitions(current_remaining - part, part, distinct)
                if cnt > k:
                    partition.append(part)
                    current_remaining -= part
                    current_max = part
                    found = True
                    break
                else:
                    k -= cnt
            if not found:
                return None
        return tuple(partition)

