import sys
from functools import lru_cache

def count_special(lo, hi, m):
    if not isinstance(lo, int) or not isinstance(hi, int) or not isinstance(m, int):
        raise ValueError
    if lo < 0 or hi < 0 or m <= 0:
        raise ValueError
    if lo > hi:
        return 0
    if m == 0:
        raise ValueError

    def count_up_to(n_str):
        n = list(map(int, n_str))
        @lru_cache(maxsize=None)
        def dp(pos, sum_mod, last_digit, tight, leading_zero):
            if pos == len(n):
                return 1 if sum_mod == 0 else 0
            limit = n[pos] if tight else 9
            total = 0
            for d in range(0, limit + 1):
                new_tight = tight and (d == limit)
                new_leading_zero = leading_zero and (d == 0)
                new_last_digit = last_digit
                new_sum_mod = sum_mod
                if new_leading_zero:
                    new_last_digit = -1
                    new_sum_mod = 0
                else:
                    if leading_zero:
                        new_sum_mod = d % m
                        new_last_digit = d
                    else:
                        if d == last_digit:
                            continue
                        new_sum_mod = (sum_mod + d) % m
                        new_last_digit = d
                total += dp(pos + 1, new_sum_mod, new_last_digit, new_tight, new_leading_zero)
            return total
        return dp(0, 0, -1, True, True)

    def to_str(x):
        return str(x)

    def subtract_one(s):
        if s == '0':
            return '0'
        num = int(s)
        num -= 1
        return str(num)

    if lo == 0:
        lower = 0
    else:
        lower_str = subtract_one(to_str(lo))
        lower = count_up_to(lower_str)
    upper_str = to_str(hi)
    upper = count_up_to(upper_str)
    return upper - lower

