def route_info(n, edges, src, dst):
    MOD = 1000000007

    # Input validation
    if not isinstance(n, int) or n < 1:
        raise ValueError("Invalid n")
    if not isinstance(edges, (list, tuple)):
        raise ValueError("Invalid edges")
    for edge in edges:
        if not isinstance(edge, (list, tuple)) or len(edge) != 3:
            raise ValueError("Invalid edge")
        u, v, w = edge
        if not isinstance(u, int) or not isinstance(v, int) or not isinstance(w, int):
            raise ValueError("Invalid edge components")
        if u < 0 or u >= n or v < 0 or v >= n:
            raise ValueError("Edge nodes out of range")
        if w < 1:
            raise ValueError("Edge weight invalid")
    if not isinstance(src, int) or not isinstance(dst, int):
        raise ValueError("Invalid src or dst")
    if src < 0 or src >= n or dst < 0 or dst >= n:
        raise ValueError("Invalid src or dst")

    if src == dst:
        return (0, 1, [src])

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm
    INF = float('inf')
    dist = [INF] * n
    count = [0] * n
    dist[src] = 0
    count[src] = 1
    heap = []
    heapq.heappush(heap, (0, src))

    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue
        for (v, w) in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                count[v] = count[u] % MOD
                heapq.heappush(heap, (dist[v], v))
            elif dist[u] + w == dist[v]:
                count[v] = (count[v] + count[u]) % MOD

    if dist[dst] == INF:
        return None

    # Reconstruct the lex smallest path
    path = []
    current = dst
    path.append(current)
    while current != src:
        min_prev = None
        for (v, w) in adj[current]:
            if dist[v] + w == dist[current] and v < current:
                if min_prev is None or v < min_prev:
                    min_prev = v
        if min_prev is None:
            return None
        path.append(min_prev)
        current = min_prev

    path.reverse()

    return (dist[dst], count[dst], path)

