    grid = [[False for _ in range(len(y_coords) - 1)] for __ in range(len(x_coords) - 1)]

    for x1, y1, x2, y2 in valid_rects:
        a = bisect.bisect_left(x_coords, x1)
        b = bisect.bisect_left(x_coords, x2)
        c = bisect.bisect_left(y_coords, y1)
        d = bisect.bisect_left(y_coords, y2)

        for i in range(a, b):
