def justify_lines(text, width):
    if not isinstance(text, str) or not isinstance(width, int) or width < 1 or isinstance(width, bool):
        raise ValueError("Invalid input")

    # Split into tokens, handling words longer than width
    tokens = []
    for word in text.split():
        if len(word) > width:
            n = len(word)
            for i in range(0, n, width):
                chunk = word[i:i+width]
                tokens.append(chunk)
        else:
            tokens.append(word)

    lines = []
    current_line = []
    current_length = 0

    for token in tokens:
        # Calculate new length if token is added
        if not current_line:
            new_length = len(token)
        else:
            new_length = current_length + 1 + len(token)

        if new_length <= width:
            current_line.append(token)
            current_length = new_length
        else:
            lines.append(current_line)
            current_line = [token]
            current_length = len(token)

    # Add the last line if not empty
    if current_line:
        lines.append(current_line)

    justified_lines = []
    num_lines = len(lines)
    for i, line in enumerate(lines):
        if i == num_lines - 1 or len(line) == 1:
            # Left-aligned
            justified = ' '.join(line)
            justified += ' ' * (width - len(justified))
        else:
