                            # Recursively compare the previous states
                            # This is a simplified approach and may not cover all cases
                            # For the sake of this solution, we assume that the path with the smaller previous color is better
                            if prev_c < existing_prev_c:
                                dp[i][key] = (new_cost, prev_c, prev_count)
                            elif prev_c == existing_prev_c:
                                # Further comparison would be needed, but this is beyond the scope here
                                pass

    last_post = dp[-1]
    if not last_post:
        return None

    min_cost = None
    best_color = None
    best_count = None
    for (c, count), (cost, _, _) in last_post.items():
        if min_cost is None or cost < min_cost:
